const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

export function buildFeed(name, now) {
  const feed = FEEDS[name];
  if (!feed) return null;
  const items = feed.items
    .filter((item) => Date.parse(item.release) <= now)
    .sort((a, b) => Date.parse(a.release) - Date.parse(b.release))
    .map((item) => {
      const page = `${SITE}/${item.id}`;  // Cloudflare Pages serves <id>.html at /<id>
      const image = `${SITE}/${item.id}.png`;
      return `<item><title>${esc(item.title)}</title><link>${page}</link>` +
        `<guid isPermaLink="true">${page}</guid>` +
        `<description>${esc(item.description)}</description>` +
        `<pubDate>${new Date(item.release).toUTCString()}</pubDate>` +
        `<enclosure url="${image}" length="${item.bytes}" type="image/png"/>` +
        `<media:content url="${image}" medium="image" type="image/png"/></item>`;
    });
  return `<?xml version="1.0" encoding="UTF-8"?>\n` +
    `<rss version="2.0" xmlns:media="http://search.yahoo.com/mrss/">` +
    `<channel><title>${esc(feed.title)}</title><link>${SITE}/</link>` +
    `<description>${esc(feed.description)}</description>` +
    items.join("") + "</channel></rss>\n";
}
